import logging
from dataclasses import dataclass, field
from pathlib import Path

log = logging.getLogger(__name__)

class LogToolError(Exception):
    """Base for everything this tool raises, so callers can catch just ours."""

class MalformedLine(LogToolError):
    pass


@dataclass
class ParseReport:
    parsed: int = 0
    skipped: list[tuple[int, str]] = field(default_factory=list)

    def summary(self) -> str:
        if not self.skipped:
            return f"Processed {self.parsed} lines, none skipped."
        from collections import Counter
        reasons = Counter(reason for _, reason in self.skipped)
        detail = "; ".join(f"{n} {reason}" for reason, n in reasons.most_common())
        return (f"Processed {self.parsed} of {self.parsed + len(self.skipped)} lines; "
                f"{len(self.skipped)} skipped: {detail}")


def parse_file(path: Path) -> tuple[list[LogEntry], ParseReport]:
    entries, report = [], ParseReport()

    # Ask forgiveness: checking path.exists() first leaves a window in which
    # the file can disappear between the check and the open.
    try:
        fh = path.open(encoding="utf-8", errors="replace")
    except FileNotFoundError as e:
        # The cause is preserved, so the real traceback is not discarded.
        raise LogToolError(f"Log file not found: {path}") from e
    except PermissionError as e:
        raise LogToolError(f"No permission to read: {path}") from e

    with fh:
        for number, line in enumerate(fh, start=1):
            try:
                entries.append(parse_line(line))
                report.parsed += 1
            except ValueError as e:
                # ONE bad line must not end a run over ten thousand. Count it,
                # keep the reason, report at the end.
                report.skipped.append((number, str(e)))
            # NOT `except Exception` — a bug in parse_line must still surface.

    return entries, report


def parse_line(line: str) -> LogEntry:
    parts = line.split()
    if len(parts) < 4:
        # The value and its shape are in the message, because the person
        # reading this does not have the file in front of them.
        raise ValueError(f"expected 4 fields, found {len(parts)}: {line[:60]!r}")
    try:
        return LogEntry(datetime.fromisoformat(parts[0]), parts[1],
                        int(parts[2]), int(parts[3]))
    except ValueError as e:
        raise ValueError(f"unparseable timestamp {parts[0]!r}") from e

import json
import pytest
from datetime import datetime, UTC

# --- structural: the client is injected, so no patching is needed ---------
class RenewalService:
    def __init__(self, http_client, now=lambda: datetime.now(UTC)):
        self._http = http_client       # injected: a fake in tests
        self._now = now                # injected clock: no waiting in tests

    def at_risk(self, region: str) -> list[dict]:
        response = self._http.get(f"/customers?region={region}")
        if response.status_code == 429:
            raise RateLimited(retry_after=int(response.headers.get("Retry-After", 60)))
        response.raise_for_status()
        today = self._now().date()
        return [c for c in response.json()["customers"]
                if (datetime.fromisoformat(c["renewal_date"]).date() - today).days <= 30]


class FakeResponse:
    def __init__(self, payload, status_code=200, headers=None):
        self._payload, self.status_code = payload, status_code
        self.headers = headers or {}
    def json(self): return self._payload
    def raise_for_status(self):
        if self.status_code >= 400:
            raise HTTPError(f"{self.status_code}")


class FakeHttp:
    def __init__(self, response): self._response = response; self.calls = []
    def get(self, url): self.calls.append(url); return self._response


# --- a recorded real response, saved once as a fixture --------------------
@pytest.fixture
def recorded_payload():
    """One real API response, captured and sanitised. Realistic — including the
    null usage field we did not expect — with no network call."""
    return json.loads(Path("tests/fixtures/customers_response.json").read_text())


def test_at_risk_returns_only_renewals_within_thirty_days(recorded_payload):
    # The clock is a parameter, so "what happens near the deadline" is testable.
    service = RenewalService(FakeHttp(FakeResponse(recorded_payload)),
                             now=lambda: datetime(2026, 9, 20, tzinfo=UTC))

    at_risk = service.at_risk("EMEA")

    assert {c["customer_id"] for c in at_risk} == {"CUST-0003", "CUST-0017"}


def test_at_risk_raises_rate_limited_with_retry_after():
    # Testing OUR handling of a 429 — the library's behaviour is not in question.
    http = FakeHttp(FakeResponse({}, status_code=429, headers={"Retry-After": "30"}))
    service = RenewalService(http)

    with pytest.raises(RateLimited) as exc:
        service.at_risk("EMEA")

    assert exc.value.retry_after == 30


