import logging, random, time
from typing import Any, Iterator
import requests
from pydantic import BaseModel, ValidationError

log = logging.getLogger(__name__)

RETRYABLE_STATUS = {429, 500, 502, 503, 504}

class Customer(BaseModel):
    customer_id: str
    name: str
    renewal_date: str
    usage_last_30d: int | None = None      # nullable in practice, despite the docs

class CustomerPage(BaseModel):
    customers: list[Customer]
    next_cursor: str | None = None


class ApiClient:
    def __init__(self, base_url: str, token: str, *, max_attempts: int = 4):
        self.base_url = base_url.rstrip("/")
        self.max_attempts = max_attempts
        # A Session reuses the TCP connection across requests.
        self._session = requests.Session()
        self._session.headers.update({"Authorization": f"Bearer {token}"})

    def _get(self, path: str, params: dict | None = None) -> dict[str, Any]:
        last_error: Exception | None = None

        for attempt in range(1, self.max_attempts + 1):
            try:
                response = self._session.get(
                    f"{self.base_url}{path}", params=params,
                    timeout=(3.05, 30),     # (connect, read). Without this, a
                )                           # silent server hangs you forever.

                if response.status_code in RETRYABLE_STATUS:
                    # Honour Retry-After; ignoring it turns a rate limit into a ban.
                    wait = float(response.headers.get("Retry-After", 0)) or self._backoff(attempt)
                    log.warning("api.retryable status=%s attempt=%d waiting=%.1fs",
                                response.status_code, attempt, wait)
                    time.sleep(wait)
                    continue

                # 4xx other than 429 will never succeed on retry.
                response.raise_for_status()
                return response.json()

            except (requests.ConnectionError, requests.Timeout) as e:
                last_error = e
                if attempt == self.max_attempts:
                    break
                time.sleep(self._backoff(attempt))

        raise ApiUnavailable(f"{path} failed after {self.max_attempts} attempts") from last_error

    @staticmethod
    def _backoff(attempt: int) -> float:
        # Jitter matters: without it every client that failed together retries
        # together and re-creates the outage they were waiting out.
        return min(2 ** attempt, 30) * (0.5 + random.random() / 2)

    def customers(self, region: str) -> Iterator[Customer]:
        cursor, pages = None, 0
        while True:
            pages += 1
            if pages > 1000:                     # bound it: a server bug that
                raise ApiError("pagination did not terminate")   # repeats a cursor
                                                                 # would spin forever
            raw = self._get("/customers", {"region": region, "cursor": cursor})
            try:
                page = CustomerPage.model_validate(raw)
            except ValidationError as e:
                # Fails HERE with a clear message, not as a KeyError three
                # functions away. Documentation and behaviour drift apart.
                raise ApiError(f"unexpected response shape from /customers: {e}") from e

            yield from page.customers
            if not page.next_cursor:
                return
            cursor = page.next_cursor

from decimal import Decimal
import psycopg
from psycopg.rows import dict_row

# --- SQL injection: the difference between safe and exploitable -----------
def find_customer_UNSAFE(conn, email: str):
    # An email of:  ' OR '1'='1
    # turns this into: SELECT * FROM customer WHERE email = '' OR '1'='1'
    # which returns every row. A more creative value drops the table.
    return conn.execute(f"SELECT * FROM customer WHERE email = '{email}'").fetchall()

def find_customer(conn, email: str):
    # The value is sent SEPARATELY from the statement and can never be parsed
    # as SQL, whatever it contains.
    return conn.execute(
        "SELECT customer_id, name, region FROM customer WHERE email = %s",
        (email,)                      # a tuple, even for one parameter
    ).fetchone()

# You cannot parameterise an identifier. Validate against an allow-list.
SORTABLE = {"name", "region", "created_at"}
def list_customers(conn, sort_by: str = "name"):
    if sort_by not in SORTABLE:
        raise ValueError(f"cannot sort by {sort_by!r}")
    return conn.execute(f"SELECT * FROM customer ORDER BY {sort_by}").fetchall()


# --- pooling and streaming large results ----------------------------------
from psycopg_pool import ConnectionPool

pool = ConnectionPool("postgresql://localhost/app", min_size=2, max_size=10)

def export_all(out_path):
    with pool.connection() as conn:              # returned to the pool automatically
        with conn.cursor(row_factory=dict_row) as cur:
            cur.execute("SELECT customer_id, name, arr FROM customer")
            while rows := cur.fetchmany(1000):   # NOT fetchall() on a large table
                for row in rows:
                    write(out_path, row)


# --- money -----------------------------------------------------------------
total = Decimal("0.00")
for row in rows:
    total += Decimal(str(row["amount"]))     # never float; drift is unexplainable

# --- pandas: state the dtypes ---------------------------------------------
import pandas as pd

df = pd.read_csv(
    "customers.csv",
    dtype={
        "customer_id": "string",     # inferred as int64 -> loses leading zeros
        "postcode":    "string",     # "01234" would become 1234
        "region":      "category",   # far less memory than object
    },
    parse_dates=["renewal_date"],
)

# For a single streaming pass over a large file, the csv module uses a
